from pathlib import Path
import json
p=Path('research/v10_maze_2h_20261001');data={'before':json.loads((p/'newfood_before.json').read_text()),'after':json.loads((p/'newfood_pursuit.json').read_text())}
html='''<!doctype html><meta charset="utf-8"><title>먹이 접근 회귀 검사</title><style>body{background:#101722;color:#eaf1fa;font:16px system-ui;margin:24px}canvas{background:#172235;border:1px solid #456;width:100%;max-width:1050px}button{padding:8px 15px;margin:4px;background:#283d55;color:white;border:1px solid #789}p{max-width:1000px;line-height:1.6}.gold{color:#ffd45a}</style><h2>회전 반경을 반영한 먹이 접근</h2><p>같은 모의 장면·명령 지연 0.17초. 선택 경로를 유지한 상태에서 2초 후 먹이를 추가했습니다. 왼쪽은 고정 방향 접근, 오른쪽은 이동 중 먹이 방향을 다시 계산한 접근입니다. 실게임 성능 증명이 아닌 회귀 검사입니다.</p><div id="buttons"></div><canvas id="c" width="1100" height="650"></canvas><p id="stats"></p><p class="gold">노랑: 새 먹이 · 빨강: 수정 전 궤적 · 초록: 수정 후 궤적 · 흰색: 먹이가 나타난 순간의 머리</p><script>const DATA='''+json.dumps(data)+''';const c=document.getElementById('c'),ctx=c.getContext('2d'),names=['근처 옆 먹이','더 먼 옆 먹이','앞쪽 먹이'],spawns=[[80,100],[80,200],[200,80]];function draw(k){ctx.clearRect(0,0,c.width,c.height);for(let panel=0;panel<2;panel++){let a=DATA[panel?'after':'before'][k],at=a.trace[59],o={x:at.x,y:at.y},cx=panel*550+250,cy=260,scale=.7;ctx.fillStyle='#fff';ctx.font='20px system-ui';ctx.fillText(panel?'수정 후':'수정 전',panel*550+25,35);ctx.strokeStyle='#34465b';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(panel*550+25,cy);ctx.lineTo(panel*550+525,cy);ctx.stroke();ctx.strokeStyle=panel?'#64eea4':'#ff7e76';ctx.lineWidth=2;ctx.beginPath();a.trace.filter(t=>t.t>=2.8&&t.t<=8).forEach((t,i)=>{let x=cx+(t.x-o.x)*scale,y=cy+(t.y-o.y)*scale;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();ctx.fillStyle='#fff';ctx.beginPath();ctx.arc(cx,cy,5,0,Math.PI*2);ctx.fill();ctx.fillStyle='#ffd45a';ctx.beginPath();ctx.arc(cx+spawns[k][0]*scale,cy+spawns[k][1]*scale,7,0,Math.PI*2);ctx.fill();ctx.fillStyle='#eaf1fa';ctx.fillText('섭취 '+a.eaten+'개 / 충돌 '+(a.dead?'있음':'없음'),panel*550+25,615);}document.getElementById('stats').textContent=names[k]+' — 세 장면 합계: 수정 전 0/3개, 수정 후 3/3개. 경로 유지와 충돌 검사를 포함한 자체 물리 모델 결과.';}names.forEach((n,k)=>{let b=document.createElement('button');b.textContent=n;b.onclick=()=>draw(k);document.getElementById('buttons').append(b)});draw(0);</script>'''
(p/'food_approach_comparison.html').write_text(html)
print(p/'food_approach_comparison.html')
